const pruneRevisions = `-- name: PruneRevisions :execrows
DELETE FROM entry_revisions r
WHERE r.id IN (
    SELECT x.id FROM entry_revisions x
    JOIN entries e ON e.id = x.entry_id
    WHERE x.id IS DISTINCT FROM e.published_revision_id
      AND x.number <= (SELECT max(y.number) FROM entry_revisions y WHERE y.entry_id = x.entry_id) - $1::int
      AND x.created_at < now() - ($2::text)::interval
)
`

type PruneRevisionsParams struct {
	Keep   int32
	MinAge string
}

func (q *Queries) PruneRevisions(ctx context.Context, arg PruneRevisionsParams) (int64, error) {
	result, err := q.db.Exec(ctx, pruneRevisions, arg.Keep, arg.MinAge)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

